css:
* {
    font-family: "Times New Roman", Times, serif !important;
    font-size: 14px !important;
}
<style>
    @page {
        size: A4;
        margin: 12mm 14mm 12mm 14mm;
    }

    * {
        font-family: "Times New Roman", Times, serif !important;
        font-size: 14px !important;
        color: #000;
    }

    body {
        margin: 0;
        font-family: "Times New Roman", Times, serif;
        font-size: 14px;
    }

    .page {
        width: 100%;
    }

    .top-line {
        display: flex;
        justify-content: space-between;
        margin-bottom: 8px;
    }

    .title {
        text-align: center;
        font-weight: bold;
        margin-bottom: 18px;
        text-decoration: underline;
    }

    .info-box {
        border: 1px solid #888;
        padding: 8px;
        margin-bottom: 8px;
    }

    .info-table {
        width: 100%;
        border-collapse: collapse;
    }

    .info-table td {
        vertical-align: top;
        padding: 0 5px;
        line-height: 1.25;
    }

    .left {
        width: 50%;
    }

    .right {
        width: 50%;
    }

    .bold {
        font-weight: bold !important;
    }



    .intro {
        margin-top: 16px;
        margin-bottom: 16px;
        line-height: 1.25;
        text-align: justify;
    }

    .items-title {
        text-align: center;
        font-weight: bold;
        border: 2px solid #000;
        border-bottom: none;
        padding: 3px;
    }

    .items-table {
        width: 100%;
        border-collapse: collapse;
        border: 2px solid #000;
    }

    .items-table th,
    .items-table td {
        border: 1px solid #777;
        padding: 4px 5px;
        vertical-align: middle;
    }

    .items-table th {
        text-align: center;
        font-weight: bold;
    }

    .item-no {
        width: 8%;
        text-align: center;
    }

    .description {
        width: 48%;
    }

    .unit-price {
        width: 17%;
        text-align: right;
    }

    .qty {
        width: 10%;
        text-align: center;
    }

    .total {
        width: 17%;
        text-align: right;
    }

    .total-row td {
        font-weight: bold;
    }

    .total-label {
        text-align: right;
    }

    .acceptance {
        margin-top: 18px;
        line-height: 1.25;
        text-align: justify;
    }

    .signature-table {
        width: 90%;
        margin: 18px auto 0 auto;
        border-collapse: collapse;
    }

    .signature-table td {
        border: 1px solid #999;
        height: 20px;
        padding: 3px 7px;
        vertical-align: middle;
    }

    .signature-header {
        height: 55px !important;
        vertical-align: top !important;
    }

    .signature-image {
        height: 48px;
        max-width: 100px;
        object-fit: contain;
    }
</style>
